-- DOWN for 029-rlm-chunk-provenance.sql
-- Drops the provenance/staleness columns and their index. Dropping
-- embedding_model loses the record of which model produced each vector; the
-- vectors themselves are unaffected and can be regenerated by a reindex.

BEGIN;

DROP INDEX IF EXISTS idx_rlm_chunks_embedding_model;

ALTER TABLE rlm_chunks DROP COLUMN IF EXISTS file_size;
ALTER TABLE rlm_chunks DROP COLUMN IF EXISTS file_mtime;
ALTER TABLE rlm_chunks DROP COLUMN IF EXISTS embedding_model;

COMMIT;
